<?php
namespace App\Services\Order;
use App\Models\Book; use App\Models\Cart; use App\Models\Order; use App\Models\User; use App\Services\Inventory\InventoryService; use Illuminate\Support\Facades\DB; use Illuminate\Support\Str; use Illuminate\Validation\ValidationException;
class OrderService { public function __construct(private readonly InventoryService $inventory) {} public function create(?User $user, ?string $token, array $address, array $itemIds, float $shippingCost = 0): Order { return DB::transaction(function() use($user,$token,$address,$itemIds,$shippingCost) { $cart=Cart::where($user?['user_id'=>$user->id]:['guest_token'=>$token])->with('items')->firstOrFail(); $items=$cart->items->whereIn('id',$itemIds); if($items->isEmpty()) throw ValidationException::withMessages(['cart'=>['Pilih minimal satu buku.']]); $order=Order::create(array_merge(['number'=>'TB-'.now()->format('Ymd').'-'.strtoupper(Str::random(6)),'user_id'=>$user?->id,'guest_token'=>$user?null:$token,'status'=>'pending_payment','subtotal'=>0,'shipping_total'=>$shippingCost,'grand_total'=>0],$address)); $total=0; $totalDiscount=0; foreach($items as $item) { $book=Book::lockForUpdate()->findOrFail($item->book_id); if(!$book->is_active || $book->stock<$item->quantity) throw ValidationException::withMessages(['cart'=>['Stok buku berubah.']]); $sub=$book->final_price*$item->quantity; $totalDiscount += ($book->price - $book->final_price) * $item->quantity; $order->items()->create(['book_id'=>$book->id,'sku'=>$book->sku,'title'=>$book->title,'author'=>$book->author,'unit_price'=>$book->final_price,'quantity'=>$item->quantity,'subtotal'=>$sub]); $this->inventory->move($book,-$item->quantity,'sale',$order,'Order '.$order->number); $total+=$sub; } $order->update(['subtotal'=>$total + $totalDiscount, 'discount_total'=>$totalDiscount, 'grand_total'=>$total + $shippingCost]); $order->histories()->create(['status'=>'pending_payment','note'=>'Order dibuat.']); $cart->items()->whereIn('id',$itemIds)->delete(); return $order->load(['items','histories']); }); } }
